"""Magias de nível 3. Tradução não oficial do SRD 5.2.1."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from spell_hl import D, H, T, X

SPELL = {
 "animate_dead": "Escolha uma pilha de ossos ou o cadáver de um Humanoide Médio ou Pequeno no alcance: vira um Esqueleto (ossos) ou Zumbi (cadáver).\n\nComo Ação Bônus, comande mentalmente as criaturas criadas a até 18 m (a mesma ordem para todas): ação e movimento do próximo turno, ou uma ordem geral (guardar um corredor). Sem ordens, usam Esquivar e só se movem para evitar dano. Ficam sob seu controle por 24 horas; conjurar de novo antes disso renova o controle de até quatro delas em vez de criar uma nova." + X("Anima ou renova o controle de mais duas criaturas por nível de espaço acima de 3, cada uma de um corpo diferente."),
 "beacon_of_hope": "Escolha quantas criaturas quiser no alcance. Pela duração, elas têm Vantagem em salvaguardas de Sabedoria e testes contra a morte, e recuperam o máximo possível de PV em qualquer cura.",
 "bestow_curse": "Você toca uma criatura, que faz salvaguarda de Sabedoria ou fica amaldiçoada pela duração, com um efeito à sua escolha:\n\nDesvantagem em testes e salvaguardas de um atributo.\nDesvantagem em jogadas de ataque contra você.\nEm combate, salvaguarda de Sabedoria no começo de cada turno ou é forçada a usar Esquivar.\nSeus ataques e magias que a ferirem causam 1d8 extra de dano Necrótico." + X("Com espaço de nível 4, a Concentração dura até 10 minutos. Com nível 5+, não exige Concentração e dura 8 horas (5–6), 24 horas (7–8) ou até ser dissipada (9)."),
 "blink": "No fim de cada turno seu, pela duração, role 1d6. Com 4–6, você vai para o Plano Etéreo (se já estiver lá, a magia termina). Lá, vê o plano que deixou em tons de cinza até 18 m e só interage com criaturas etéreas, que são as únicas que te percebem (salvo habilidades especiais). No começo do seu próximo turno, e ao fim da magia, volta a um espaço que você vê a até 3 m de onde saiu.",
 "call_lightning": "Uma nuvem de tempestade surge acima de você num ponto que você vê no alcance: um Cilindro de 3 m de altura e 18 m de raio. Ao conjurar, escolha um ponto sob a nuvem: um raio cai e cada criatura a até 1,5 m faz salvaguarda de Destreza, 3d10 de dano Elétrico na falha, metade no sucesso. Até a magia acabar, com a ação Magia, chame outro raio. Ao ar livre numa tempestade, você a controla e o dano aumenta em 1d10." + D("1d10", 3),
 "clairvoyance": "Você cria um sensor Invisível, intangível e invulnerável no alcance, num lugar que conhece ou num local óbvio (atrás de uma porta, depois de uma esquina). Escolha visão ou audição e use esse sentido como se estivesse lá; como Ação Bônus, alterne. Quem enxerga o invisível vê um orbe luminoso do tamanho de um punho.",
 "conjure_animals": "Você conjura espíritos da natureza como uma matilha Grande de animais espectrais e intangíveis (lobos, serpentes, aves) num espaço que você vê no alcance.\n\nVocê tem Vantagem em salvaguardas de Força a até 1,5 m da matilha e, ao se mover no seu turno, pode movê-la até 9 m. Quando ela chega a até 3 m de uma criatura que você vê, ou uma criatura entra ou termina o turno a até 3 m dela, você pode forçar uma salvaguarda de Destreza: 3d10 de dano Cortante na falha (uma vez por turno por criatura)." + D("1d10", 3),
 "counterspell": "Você tenta interromper uma criatura que está conjurando uma magia. Ela faz salvaguarda de Constituição. Na falha, a magia se dissipa sem efeito e a ação, Ação Bônus ou Reação usada é perdida; se usou espaço de magia, ele não é gasto.",
 "create_food_and_water": "Você cria 20 kg de comida e 120 litros de água limpa no chão ou em recipientes no alcance. A comida é sem graça mas nutritiva, com a aparência que quiser, e estraga em 24 horas se não for comida.",
 "daylight": "Pela duração, luz do sol enche uma Esfera de 18 m de raio a partir de um ponto no alcance (Luz Plena, com Penumbra por mais 18 m). Conjurada num objeto, enche uma Emanação de 18 m dele (cobri-lo bloqueia). Dissipa Escuridão de magias de nível 3 ou menor que se sobreponham.",
 "dispel_magic": "Escolha uma criatura, objeto ou efeito mágico no alcance. Magias de nível 3 ou menor nele terminam. Para cada magia de nível 4+, faça um teste com seu atributo de conjuração (CD 10 + nível da magia); no sucesso, ela termina." + X("Encerra automaticamente magias de nível igual ou menor que o espaço usado."),
 "fear": "Cada criatura num Cone de 9 m faz salvaguarda de Sabedoria ou larga o que segura e fica Amedrontada pela duração. Amedrontada, usa Disparada e foge de você pelo caminho mais seguro a cada turno. Se terminar o turno sem linha de visão até você, repete a salvaguarda; no sucesso, a magia termina para ela.",
 "fireball": "Um risco brilhante sai de você até um ponto no alcance e explode em chamas. Cada criatura numa Esfera de 6 m de raio faz salvaguarda de Destreza: 8d6 de dano de Fogo na falha, metade no sucesso. Objetos inflamáveis na área que não estejam sendo vestidos ou carregados pegam fogo." + D("1d6", 3),
 "fly": "Você toca uma criatura voluntária. Pela duração, ela ganha Deslocamento de Voo de 18 m e pode pairar. Ao fim, cai se ainda estiver no ar, a menos que consiga evitar." + T(3),
 "gaseous_form": "Uma criatura voluntária que você toca vira, com tudo que carrega, uma nuvem de névoa pela duração (termina a 0 PV ou com a ação Magia dela).\n\nSó se move com Voo de 3 m, podendo pairar e ocupar o espaço de outras criaturas. Tem Resistência a dano contundente, perfurante e cortante, Imunidade a Caído e Vantagem em salvaguardas de Força, Destreza e Constituição. Passa por frestas, mas trata líquidos como sólidos. Não fala, não manipula objetos, não ataca nem conjura." + T(3),
 "glyph_of_warding": "Você inscreve um glifo quase imperceptível (Sabedoria (Percepção) contra sua CD para notar) numa superfície ou dentro de um objeto que fecha, cobrindo até 3 m de diâmetro. Se for movido mais de 3 m, se quebra.\n\nGatilho. Você define o que o ativa (tocar, pisar, abrir, aproximar-se), podendo restringir a tipos de criatura ou criar exceções (senha). Ativado, a magia termina.\nRuna Explosiva. Esfera de 6 m de raio: salvaguarda de Destreza, 5d8 de dano Ácido, de Frio, Fogo, Elétrico ou Trovejante (escolhido ao criar) na falha, metade no sucesso.\nGlifo de Magia. Armazene uma magia preparada de nível 3 ou menor que tenha alvo único ou área; ao ativar, ela afeta quem disparou (ou centra a área nele). Concentração dura o tempo total." + X("A runa explosiva causa +1d8 por nível de espaço acima de 3, e o glifo de magia armazena magias até o nível do espaço usado."),
 "haste": "Escolha uma criatura voluntária que você vê no alcance. Até a magia acabar, o Deslocamento dela dobra, ela ganha +2 na CA, Vantagem em salvaguardas de Destreza e uma ação extra por turno, só para Atacar (um ataque), Disparada, Desengajar, Esconder ou Utilizar. Ao fim, fica Incapacitada e com Deslocamento 0 até o fim do próximo turno dela.",
 "hypnotic_pattern": "Um padrão de cores retorcidas surge num Cubo de 9 m no alcance e some. Cada criatura na área que o veja faz salvaguarda de Sabedoria ou fica Enfeitiçada pela duração; nesse estado, fica Incapacitada e com Deslocamento 0. Termina para ela se sofrer dano ou alguém usar uma ação para sacudi-la.",
 "lightning_bolt": "Um raio forma uma Linha de 30 m por 1,5 m a partir de você, na direção que escolher. Cada criatura na Linha faz salvaguarda de Destreza: 8d6 de dano Elétrico na falha, metade no sucesso." + D("1d6", 3),
 "magic_circle": "Você cria um Cilindro de energia de 3 m de raio e 6 m de altura num ponto no chão que você vê no alcance, com runas brilhantes. Escolha Celestiais, Elementais, Fadas, Corruptores e/ou Mortos-Vivos. Criaturas desses tipos não entram voluntariamente por meios não mágicos (teleporte exige salvaguarda de Carisma), têm Desvantagem nos ataques contra alvos dentro e não podem possuir, Enfeitiçar ou Amedrontar quem está dentro. Você pode inverter o círculo para prender essas criaturas dentro." + X("A duração aumenta em 1 hora por nível de espaço acima de 3."),
 "major_image": "Você cria a imagem de um objeto, criatura ou fenômeno de até um Cubo de 6 m num ponto que você vê no alcance, com som, cheiro e temperatura, mas sem causar dano ou condições. Com a ação Magia (estando no alcance), mova-a e faça-a agir e falar de forma natural. Interagir fisicamente revela a ilusão; com a ação Estudar e um teste de Inteligência (Investigação) contra sua CD, uma criatura a percebe e passa a ver através dela." + X("Com espaço de nível 4+, dura até ser dissipada, sem Concentração."),
 "mass_healing_word": "Até seis criaturas à sua escolha que você vê no alcance recuperam PV iguais a 2d4 + seu modificador de conjuração." + H("1d4", 3),
 "meld_into_stone": "Você entra num objeto ou superfície de pedra grande o bastante para conter seu corpo, fundindo-se a ela com seu equipamento pela duração, sem deixar sinal detectável por sentidos não mágicos. Lá dentro não vê o exterior, tem Desvantagem em Sabedoria (Percepção) para ouvir, percebe o tempo e pode conjurar magias em si. Sair custa 1,5 m de movimento e encerra a magia.\n\nDanos leves à pedra não te ferem; destruição parcial ou mudança de forma te expulsa com 6d6 de dano de Energia; destruição total, 50 de dano de Energia. Expulso, você fica Caído no espaço livre mais próximo.",
 "nondetection": "Pela duração, você esconde de magias de Adivinhação um alvo que toca: criatura voluntária, ou lugar ou objeto de até 3 m. Ele não pode ser alvo de Adivinhação nem percebido por sensores de vidência.",
 "phantom_steed": "Uma criatura quase real parecida com um cavalo, Grande, surge no chão num espaço no alcance, com sela, freio e rédeas (que somem a mais de 3 m dela). Pela duração, você ou alguém que escolher pode montá-la: estatísticas de Cavalo de Montaria, mas Deslocamento 30 m e 20 km por hora. Ao fim, some aos poucos (1 minuto para desmontar). Termina se ela sofrer dano.",
 "plant_growth": "Canaliza vitalidade nas plantas; o tempo de conjuração define o efeito:\n\nCrescimento Excessivo (ação). Plantas numa Esfera de 30 m de raio no alcance ficam densas: cada 30 cm de movimento custa 1,2 m. Você pode excluir áreas.\nEnriquecimento (8 horas). Plantas num raio de 800 m rendem o dobro de comida por 365 dias (uma vez por ano).",
 "protection_from_energy": "Pela duração, a criatura voluntária que você toca tem Resistência a um tipo de dano à sua escolha: Ácido, Frio, Fogo, Elétrico ou Trovejante.",
 "remove_curse": "Ao seu toque, todas as maldições numa criatura ou objeto terminam. Num item mágico amaldiçoado, a maldição permanece, mas a Sintonia do dono se rompe para que possa descartá-lo.",
 "revivify": "Você toca uma criatura que morreu no último minuto: ela volta à vida com 1 PV. Não revive quem morreu de velhice nem restaura partes perdidas do corpo.",
 "sending": "Você envia uma mensagem de até 25 palavras a uma criatura que conhece ou que lhe foi descrita por alguém que a conhece. Ela ouve na mente, reconhece você se te conhece, entende o sentido e pode responder na hora. Funciona a qualquer distância e entre planos (5% de chance de falhar se em outro plano; você sabe se falhou). Quem recebe pode bloquear novas mensagens suas por 8 horas.",
 "sleet_storm": "Até a magia acabar, granizo cai num Cilindro de 12 m de altura e 6 m de raio num ponto no alcance: área Densamente Obscurecida, chamas expostas se apagam e o chão é Terreno Difícil. Quem entrar pela primeira vez no turno ou começar o turno ali faz salvaguarda de Destreza ou fica Caído e perde a Concentração.",
 "slow": "Você altera o tempo ao redor de até seis criaturas à sua escolha num Cubo de 12 m no alcance. Cada uma faz salvaguarda de Sabedoria ou, pela duração, tem o Deslocamento reduzido à metade, −2 na CA e em salvaguardas de Destreza, sem Reações; no turno, usa ação ou Ação Bônus (não ambas) e só um ataque com Atacar. Magias com componente Somático têm 25% de chance de falhar. Repete a salvaguarda no fim de cada turno.",
 "speak_with_dead": "Você dá um simulacro de vida a um cadáver com boca no alcance (falha se era Morto-Vivo ou se foi alvo desta magia nos últimos 10 dias). Até a magia acabar, faça até cinco perguntas. Ele só sabe o que sabia em vida, responde de forma breve ou enigmática e não é obrigado a dizer a verdade se te vir como inimigo. Não aprende nada novo nem especula sobre o futuro.",
 "speak_with_plants": "Plantas numa Emanação fixa de 9 m ganham sentiência limitada: comunicam-se com você, seguem ordens simples e contam o que aconteceu ali no último dia (quem passou, o clima). Você pode transformar Terreno Difícil de vegetação em normal, ou o contrário, pela duração. Elas não se desenraízam, mas movem galhos e cipós. Criaturas Planta na área conversam com você como se tivessem idioma em comum.",
 "spirit_guardians": "Espíritos protetores voam ao seu redor numa Emanação de 4,5 m pela duração (angelicais ou feéricos se você for bom ou neutro; corruptores se for mau). Você designa criaturas não afetadas. As demais têm o Deslocamento reduzido à metade na área e, quando a área chega a elas, entram ou terminam o turno nela, fazem salvaguarda de Sabedoria: 3d8 de dano Radiante (ou Necrótico, se você for mau) na falha, metade no sucesso, uma vez por turno." + D("1d8", 3),
 "stinking_cloud": "Uma Esfera de 6 m de raio de gás amarelo nauseante surge num ponto no alcance, Densamente Obscurecida, pela duração ou até um vento forte dispersá-la. Quem começar o turno nela faz salvaguarda de Constituição ou fica Envenenado até o fim do turno, sem poder usar ação nem Ação Bônus.",
 "tiny_hut": "Uma Emanação fixa de 3 m surge ao seu redor pela duração (falha se não couber todas as criaturas na área). Quem estava dentro ao conjurar passa livremente; o resto não atravessa, e magias de nível 3 ou menor não passam. Dentro, o clima é seco e confortável; você escolhe Penumbra ou Escuridão. É opaca por fora e transparente por dentro. Termina se você sair ou conjurar de novo.",
 "tongues": "A criatura que você toca entende qualquer idioma falado ou sinalizado que perceba, e qualquer criatura que conheça um idioma entende o que ela fala ou sinaliza.",
 "vampiric_touch": "Sua mão envolta em sombras drena vida. Faça um ataque mágico corpo a corpo contra uma criatura ao alcance: se acertar, 3d6 de dano Necrótico, e você recupera PV iguais a metade do dano. Até a magia acabar, repita o ataque a cada turno com a ação Magia." + D("1d6", 3),
 "water_breathing": "Até dez criaturas voluntárias à sua escolha no alcance respiram debaixo d'água até a magia acabar, mantendo a respiração normal.",
 "water_walk": "Até dez criaturas voluntárias à sua escolha no alcance andam sobre qualquer líquido (água, ácido, lama, neve, areia movediça, lava) como se fosse chão firme, pela duração (lava ainda queima pelo calor). Passar da superfície para dentro do líquido, e vice-versa, custa uma Ação Bônus; quem cair atravessa a superfície.",
 "wind_wall": "Uma muralha de vento forte se ergue num ponto no alcance: até 15 m de comprimento, 4,5 m de altura e 30 cm de espessura, em qualquer formato contínuo, pela duração. Ao surgir, cada criatura na área faz salvaguarda de Força: 4d8 de dano Contundente na falha, metade no sucesso. Afasta neblina e gases; criaturas ou objetos voadores Pequenos ou menores não passam; flechas e projéteis comuns são desviados e erram (pedras de Gigantes e máquinas de cerco não). Criaturas em forma gasosa não atravessam.",
}
